import static org.junit.jupiter.api.Assertions.*;

/**
 * Unit tests for CommandLine#getParsedOptionValues(String)
 */
public class CommandLine_GetParsedOptionValues_String_Test {

    /**
     * A small test subclass that overrides getParsedOptionValues(Option)
     * so we can verify delegation from getParsedOptionValues(String).
     */
    private static class TestCommandLine extends CommandLine {
        @Override
        @SuppressWarnings("unchecked")
        public <T> T[] getParsedOptionValues(final Option option) {
            // return a known String[] to assert delegation
            return (T[]) new String[] { "v1", "v2" };
        }
    }

    @Test
    public void whenOptionNameIsNull_thenReturnsNull() throws Exception {
        // use protected no-arg constructor
        final CommandLine cmd = new CommandLine();
        // calling with null should cause resolveOption to yield null and result to be null
        final String[] values = cmd.getParsedOptionValues((String) null);
        assertNull(values, "Expected null when optionName is null");
    }

    @Test
    public void whenOptionNameDoesNotMatchAnyOption_thenReturnsNull() throws Exception {
        final CommandLine cmd = new CommandLine();
        // no options configured -> no match
        final String[] values = cmd.getParsedOptionValues("nonexistent");
        assertNull(values, "Expected null for a non-existent option");
    }

    @Test
    public void whenOptionNameMatchesShortOrLongOpt_thenDelegatesAndReturnsValues() throws Exception {
        final TestCommandLine cmd = new TestCommandLine();

        // prepare an options list containing an Option that will match "a" and "alpha"
        final List<Option> optionList = new ArrayList<>();
        // Use the Option constructor (opt, longOpt, hasArg, description)
        optionList.add(new Option("a", "alpha", false, "desc"));

        // inject the options list into the private final 'options' field via reflection
        final Field optionsField = CommandLine.class.getDeclaredField("options");
        optionsField.setAccessible(true);
        optionsField.set(cmd, optionList);

        // call with short opt
        final String[] shortResult = cmd.getParsedOptionValues("a");
        assertArrayEquals(new String[] { "v1", "v2" }, shortResult, "Expected delegated values for short opt");

        // call with leading hyphens on long opt (resolveOption strips hyphens)
        final String[] longResult = cmd.getParsedOptionValues("--alpha");
        assertArrayEquals(new String[] { "v1", "v2" }, longResult, "Expected delegated values for long opt with leading hyphens");
    }
}

